{
  "$schema": "https://json.schemastore.org/claude-code-plugin-manifest.json",
  "name": "dr-cockpit",
  "description": "A Claude Code mod for long sessions: a cockpit pane of what the session is doing, context against its handoff budget, usage limits with forecasts, subagents, the dr-superpowers run and the repo; Discord notifications when a turn needs you or ends; and a guard that keeps AI attribution out of commits and pull requests.",
  "version": "0.6.2",
  "author": {
    "name": "Darkraise"
  },
  "homepage": "https://github.com/darkraise/darkraise-ai-plugins/tree/main/plugins/dr-cockpit",
  "repository": "https://github.com/darkraise/darkraise-ai-plugins",
  "license": "MIT",
  "keywords": [
    "mod",
    "context-window",
    "handoff",
    "subagents",
    "token-usage",
    "attribution",
    "rate-limits",
    "git"
  ],
  "types": "./types/index.d.ts",
  "userConfig": {
    "handoffTokens": {
      "type": "number",
      "title": "Handoff budget (tokens)",
      "description": "Context size at which the band says hand off. 0 follows DR_SUPERPOWERS_BUDGET, else dr-superpowers' rule: 93% of the smaller of autoCompactWindow and the model's window, minus 140,000.",
      "default": 0
    },
    "nudgeModel": {
      "type": "boolean",
      "title": "Tell the model at the budget",
      "description": "In a session running dr-superpowers, add one note to the conversation when the main session crosses its handoff budget.",
      "default": true
    },
    "guardAttribution": {
      "type": "boolean",
      "title": "Keep AI attribution out of git",
      "description": "Drop the commit trailer and pull request footer Claude Code asks for, and refuse commits and pull requests that still carry AI attribution.",
      "default": true
    },
    "warnAt": {
      "type": "number",
      "title": "Warn at (% of the handoff budget)",
      "description": "Where the strip above the prompt starts showing the handoff reading, as a share of the handoff budget, 1 to 99.",
      "default": 80
    },
    "layout": {
      "type": "string",
      "title": "Pane layout",
      "description": "auto, full or compact. auto: the full layout docked beside the transcript, the compact strip (dr-status' two framed lines and the buttons) when the pane sits above the prompt. full or compact: always that one. Anything else counts as auto.",
      "default": "auto"
    },
    "sections": {
      "type": "string",
      "title": "Pane sections",
      "description": "Which sections the full pane shows, in order, comma-separated: account, context, usage, shells, agents, plan, repo, guard. Empty shows all eight.",
      "default": ""
    },
    "breakdownRows": {
      "type": "number",
      "title": "Context breakdown rows",
      "description": "How many /context categories the Context section lists, largest first, up to 12. 0 hides the breakdown.",
      "default": 6
    },
    "openAtStart": {
      "type": "boolean",
      "title": "Open the pane at session start",
      "description": "Open the cockpit when a session starts. Claude Code shows it once the terminal is 144 columns wide, 110 once you have opened it before; /cockpit opens it at any width.",
      "default": true
    },
    "limitAlertAt": {
      "type": "number",
      "title": "Usage limit alert (%)",
      "description": "Show a toast once when the 5-hour or 7-day limit crosses this share, again after it resets. 0 turns it off.",
      "default": 90
    },
    "notifyOn": {
      "type": "string",
      "title": "Discord: events to send",
      "description": "Comma-separated: ask, question, done, error, blocked, budget, limit, task, session, agent. Empty sends ask, question, done, error, blocked, budget and limit; none sends nothing. The webhook itself is set in the cockpit's settings view.",
      "default": ""
    },
    "notifyAfter": {
      "type": "number",
      "title": "Discord: done after (seconds)",
      "description": "A finished turn is sent only when it ran at least this long. 0 sends every turn.",
      "default": 60
    },
    "notifyAskAfter": {
      "type": "number",
      "title": "Discord: approval after (seconds)",
      "description": "An approval or question is sent only when it is still unanswered after this long. 0 sends at once.",
      "default": 20
    },
    "notifyDetail": {
      "type": "string",
      "title": "Discord: detail",
      "description": "full sends command, question and answer excerpts (secrets masked); brief sends titles and figures only.",
      "default": "full"
    }
  }
}

files.types/index.d.ts:
/** The main session's context against its handoff budget, as last read. */
export type CockpitBudget = {
  /** Input tokens the last main-loop response was answered over. */
  tokens: number
  /** The handoff budget in tokens. */
  limit: number
  /** The model's context window in tokens. */
  window: number
  /** The auto-compaction window from the settings, when one is set. */
  compactWindow: number | null
  /** What the session has cost so far, in US dollars, when the host says. */
  usd: number | null
}

/** One rate-limit window as the last response reported it. */
export type CockpitLimit = {
  /** `five_hour`, `seven_day`, or a gateway's `spend_limit`. */
  kind: string
  percent: number
  /** When the window resets, in milliseconds since the epoch. */
  resetsAt: number | null
}

/** The account's limits and the session's spend, from the last measurement. */
export type CockpitUsage = {
  limits: CockpitLimit[]
  /** When the session began, in milliseconds since the epoch. */
  startedAt: number
  /** When these figures were read, in milliseconds since the epoch. */
  readAt: number
}

/** One row of the /context breakdown. */
export type CockpitContextRow = {
  name: string
  tokens: number
}

/** The /context breakdown, estimated locally. */
export type CockpitBreakdown = {
  rows: CockpitContextRow[]
  /** The token count at which auto-compaction runs, when it is on. */
  compactAt: number | null
}

/** One subagent type's runs and tokens this session. */
export type CockpitSeat = {
  seat: string
  runs: number
  input: number
  cacheRead: number
  cacheWrite: number
  output: number
}

/** One subagent the session started. */
export type CockpitSpawn = {
  agentId: string
  seat: string
  model: string
  description: string
  isDone: boolean
  /** When it started, in milliseconds since the epoch. */
  startedAt: number
}

/** One background shell the session started and has not heard the end of. */
export type CockpitShell = {
  /** The background task's id, as its notification names it. */
  id: string
  command: string
  /** When it went to the background, in milliseconds since the epoch. */
  startedAt: number
}

/** Remote Control as the cockpit sees it. */
export type CockpitRemote = {
  /** The remote clients attached now (a phone, the desktop app). */
  clients: { id: string; surface: string }[]
  /** The `/config` row "Enable Remote Control for all sessions": `true`, `false` or `default`. */
  setting: string | null
}

/** One item of the session's todo or task list. */
export type CockpitPlanItem = {
  id: string
  text: string
  status: 'pending' | 'in_progress' | 'completed'
}

/** The working directory's git state. */
export type CockpitRepo = {
  branch: string
  ahead: number
  behind: number
  changed: number
  untracked: number
}

/** A git write the attribution guard refused. */
export type CockpitRefusal = {
  at: number
  tool: string
  line: string
}

/** The account the session runs as, from its .claude.json and dr-status' config. */
export type CockpitAccount = {
  email: string | null
  name: string | null
  organization: string | null
  role: string | null
  /** Claude's billing type, such as `stripe_subscription`. */
  billing: string | null
  /** The config directory as dr-status keys it: `~/.claude`, `~/.claude-work`. */
  key: string
  /** The frame color dr-status assigns this account, as configured. */
  color: string | null
}

/** Where the session runs, for the status strip's path. */
export type CockpitPlace = {
  cwd: string
  /** The repository's root, when the working directory is in one. */
  root: string | null
  /** The repository's `origin` remote URL, when it has one. */
  remote?: string | null
  home: string | null
}

/** The main loop's model, effort and cache hit rate, as its last request had them. */
export type CockpitEngine = {
  model: string | null
  effort: string | null
  /** The share of the last main turn's input served from the cache, 0 to 1. */
  cache: number | null
}

/** What the session is doing now, for the Now row and the state file. */
export type CockpitActivity = {
  /** `waiting` on an approval, `asking` a question, `failed` once a turn ended in an error, `interrupted` once Esc stopped it. */
  kind: 'idle' | 'running' | 'waiting' | 'asking' | 'failed' | 'interrupted'
  /** When this state began, in milliseconds since the epoch. */
  since: number
  /** When the running turn began. */
  turnStartedAt: number | null
  /** The main loop's request count this turn. */
  step: number
  /** The tool in flight, and the subagent seat running it. */
  tool: string | null
  agent: string | null
  /** What waits on the person, or why the turn failed. */
  detail: string | null
  lastTurnMs: number | null
  endedAt: number | null
  /** Whether a Discord message went out for this state. */
  isSent: boolean
}

/** One task of a dr-superpowers run, from its plan and its ledger. */
export type CockpitRunTask = {
  n: number
  title: string
  state: 'pending' | 'assigned' | 'complete' | 'blocked'
  /** The fix or review round in flight, "2/5". */
  round: string | null
  seat: string | null
  isClean: boolean
  reason: string | null
}

/** A dr-superpowers run as its SDD ledger tells it. */
export type CockpitRun = {
  plan: string | null
  tasks: CockpitRunTask[]
  done: number
  total: number
  isFinished: boolean
}

/**
 * What dr-superpowers finishing does if its menu goes unanswered, as its
 * `finish-choice` script keeps it (finish.json). Times in milliseconds.
 */
export type CockpitFinish = {
  action: 'merge' | 'pr' | 'keep' | 'wait'
  base: string | null
  /** When the menu's 30 minutes run out, once finishing armed the choice. */
  dueAt: number | null
  /** Your own answer to the menu, which overrides the choice. */
  answer: string | null
  /** When the wake carried the choice out. */
  firedAt: number | null
}

/** The Discord webhook's state, as the settings view shows it. */
export type CockpitNotifier = {
  /** The webhook URL; never drawn, only masked. */
  url: string | null
  isFromEnv: boolean
  /** The Discord user id that ping messages mention. */
  mention: string | null
  /** The field being edited in the settings view. */
  editing: 'url' | 'mention' | null
  /** Why the last edit was refused. */
  error: string | null
  /** The last send's outcome. */
  last: { at: number; text: string; isError: boolean } | null
}

declare module 'claude-code' {
  interface PluginState {
    'dr-cockpit': {
      budget: CockpitBudget | null
      usage: CockpitUsage | null
      breakdown: CockpitBreakdown | null
      seats: CockpitSeat[]
      spawns: CockpitSpawn[]
      shells: CockpitShell[]
      remote: CockpitRemote
      plan: CockpitPlanItem[]
      repo: CockpitRepo | null
      refusals: CockpitRefusal[]
      account: CockpitAccount | null
      place: CockpitPlace | null
      engine: CockpitEngine
      /** Rate-limit windows already alerted, as `<kind>@<resetsAt>`. */
      alerted: string[]
      /** The main session's context readings, oldest first, for the trend line. */
      trend: number[]
      /** Whether the pane shows the cockpit or its settings. */
      view: 'cockpit' | 'settings'
      activity: CockpitActivity
      /** The main session's context at the end of each turn, oldest first, for the forecast. */
      turnTokens: number[]
      run: CockpitRun | null
      finish: CockpitFinish | null
      /** When the newest handoff note was written, in milliseconds since the epoch. */
      handoffAt: number | null
      notifier: CockpitNotifier
      isNudged: boolean
      isPlanSession: boolean
    }
  }
}
